#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<long long> ones_sequence(20), powers_of_10(20);
int minimal_moves = -1;

void setup()
{
    powers_of_10[0] = 1;
    for (int i = 1; i <= 17; ++i)
        powers_of_10[i] = powers_of_10[i - 1] * 10;

    ones_sequence[0] = 0;
    for (int i = 1; i <= 17; ++i)
        ones_sequence[i] = ones_sequence[i - 1] * 10 + 1;
}

int get_number_length(long long num)
{
    int length = 0;
    do
    {
        ++length;
        num /= 10;
    } while (num != 0);
    return length;
}

void explore(int digit_count, long long value, int steps)
{
    if (minimal_moves != -1 && steps >= minimal_moves)
        return;
    if (value == 0 || digit_count == 0)
    {
        if (minimal_moves == -1 || steps < minimal_moves)
            minimal_moves = steps;
        return;
    }
    if (value < 0)
        value = -value;

    long long temp_value = value;
    int temp_steps = 0;
    while (temp_value >= powers_of_10[digit_count - 1])
    {
        temp_value -= ones_sequence[digit_count];
        temp_steps += digit_count;
    }
    explore(digit_count - 1, temp_value, steps + temp_steps);

    temp_value = ones_sequence[digit_count + 1] - value;
    temp_steps = 0;
    while (temp_value >= powers_of_10[digit_count - 1])
    {
        temp_value -= ones_sequence[digit_count];
        temp_steps += digit_count;
    }
    explore(digit_count - 1, temp_value, steps + digit_count + 1 + temp_steps);
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    setup();

    long long num_input;
    cin >> num_input;
    minimal_moves = -1;
    explore(get_number_length(num_input), num_input, 0);
    cout << minimal_moves << "\n";

    return 0;
}
